pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(recipient != address(0));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        try c.withdrawAll(recipient) {} catch {}
        uint256 balanceAfter = address(c).balance;
        bool isOwner = caller == c.owner();
        if (isOwner) {
            assertTrue(balanceAfter == 0);
        } else {
            assertTrue(balanceAfter == balanceBefore);
        }
    }
}

