pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint96 preBal, uint96 additional) public {
        vm.assume(recipient != address(0) && recipient != address(c) && recipient != address(this));
        uint256 pre = uint256(preBal);
        uint256 add = uint256(additional);
        vm.assume(pre > 0 && add > 0 && pre + add > pre);
        vm.deal(address(c), pre);
        vm.deal(recipient, 0);
        vm.deal(address(this), add);
        vm.prank(address(this));
        (bool fundedOk, ) = address(c).call{value: add}("");
        require(fundedOk, "funding failed");
        uint256 cBalBefore = address(c).balance;
        uint256 recBalBefore = recipient.balance;
        vm.prank(address(this));
        c.withdrawAll(recipient);
        uint256 recBalAfter = recipient.balance;
        assertTrue(recBalAfter == recBalBefore + cBalBefore);
    }
}
